G=load()
def f(I):
    I=np.array(I); H,W=I.shape
    ms=[tuple(p) for p in np.argwhere(I==5)]
    pcells=[(r,c,int(I[r][c])) for r in range(H) for c in range(W) if I[r][c]!=5]
    o=[[0]*W for _ in range(H)]
