        ni,nj=r+v[0],c+v[1]
        if 0<=ni<H and 0<=nj<W and (ni,nj)!=(ms[0] and tuple(ms[0])):
            o[ni][nj]=vv
    # erase markers
    for m in ms: o[m[0]][m[1]]=0
    return o
